package com.optarena.inventory

import com.jayway.jsonpath.JsonPath
import com.optarena.inventory.repository.ItemRepository
import com.optarena.inventory.repository.WarehouseRepository
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.http.MediaType
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status

@SpringBootTest
@AutoConfigureMockMvc
class TransferItemsAtomicTest {

    @Autowired
    private lateinit var mockMvc: MockMvc

    @Autowired
    private lateinit var warehouseRepository: WarehouseRepository

    @Autowired
    private lateinit var itemRepository: ItemRepository

    @BeforeEach
    fun resetState() {
        warehouseRepository.clear()
        itemRepository.clear()
    }

    private fun createWarehouse(maxCapacity: Int? = null): Int {
        val body = if (maxCapacity != null) """{"name":"W","location":"x","maxCapacity":$maxCapacity}"""
                    else """{"name":"W","location":"x"}"""
        val resp = mockMvc.perform(post("/api/warehouses").contentType(MediaType.APPLICATION_JSON).content(body))
            .andReturn().response.contentAsString
        return JsonPath.read(resp, "$.id")
    }

    private fun createItem(warehouseId: Int, sku: String, quantity: Int): Int {
        val resp = mockMvc.perform(
            post("/api/items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"sku":"$sku","name":"$sku","warehouseId":$warehouseId,"quantity":$quantity}""")
        ).andReturn().response.contentAsString
        return JsonPath.read(resp, "$.id")
    }

    @Test
    fun transferIsAtomicOnForeignItem() {
        val from = createWarehouse()
        val to = createWarehouse()
        val other = createWarehouse()

        val item1 = createItem(from, "A", 5)
        val foreignItem = createItem(other, "B", 1)

        mockMvc.perform(
            post("/api/warehouses/$from/transfer-items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"toWarehouseId":$to,"itemIds":[$item1,$foreignItem]}""")
        ).andExpect(status().isBadRequest)

        mockMvc.perform(get("/api/items/$item1"))
            .andExpect(jsonPath("$.warehouseId").value(from))
    }

    @Test
    fun transferMovesAllItemsWhenEveryIdBelongsToSource() {
        val from = createWarehouse()
        val to = createWarehouse()
        val item1 = createItem(from, "A", 5)

        mockMvc.perform(
            post("/api/warehouses/$from/transfer-items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"toWarehouseId":$to,"itemIds":[$item1]}""")
        ).andExpect(status().isOk)

        mockMvc.perform(get("/api/items/$item1"))
            .andExpect(jsonPath("$.warehouseId").value(to))
    }
}

