package com.optarena.inventory.controller

import com.optarena.inventory.model.Item
import com.optarena.inventory.model.Warehouse
import com.optarena.inventory.repository.ItemRepository
import com.optarena.inventory.repository.WarehouseRepository
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.server.ResponseStatusException

data class CreateWarehouseRequest(val name: String? = null, val location: String? = null, val maxCapacity: Int? = null)

data class TransferItemsRequest(val toWarehouseId: Long? = null, val itemIds: List<Long> = emptyList())

@RestController
class WarehouseController(
    private val warehouseRepository: WarehouseRepository,
    private val itemRepository: ItemRepository
) {

    @PostMapping("/api/warehouses")
    @ResponseStatus(HttpStatus.CREATED)
    fun createWarehouse(@RequestBody body: CreateWarehouseRequest): Warehouse {
        val name = body.name?.trim().orEmpty()
        val location = body.location?.trim().orEmpty()
        if (name.isEmpty()) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "name is required")
        }
        if (location.isEmpty()) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "location is required")
        }
        if (body.maxCapacity != null && body.maxCapacity < 0) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "maxCapacity must be a non-negative integer")
        }
        return warehouseRepository.save(Warehouse(name = name, location = location, maxCapacity = body.maxCapacity))
    }

    @GetMapping("/api/warehouses")
    fun listWarehouses(): List<Warehouse> = warehouseRepository.findAll()

    @GetMapping("/api/warehouses/{id}")
    fun getWarehouse(@PathVariable id: Long): Warehouse =
        warehouseRepository.findById(id) ?: throw ResponseStatusException(HttpStatus.NOT_FOUND, "warehouse not found")

    @PostMapping("/api/warehouses/{fromId}/transfer-items")
    fun transferItems(@PathVariable fromId: Long, @RequestBody body: TransferItemsRequest): List<Item> {
        warehouseRepository.findById(fromId)
            ?: throw ResponseStatusException(HttpStatus.NOT_FOUND, "source warehouse not found")
        val toId = body.toWarehouseId
            ?: throw ResponseStatusException(HttpStatus.BAD_REQUEST, "toWarehouseId must reference an existing warehouse")
        val toWarehouse = warehouseRepository.findById(toId)
            ?: throw ResponseStatusException(HttpStatus.BAD_REQUEST, "toWarehouseId must reference an existing warehouse")
        if (body.itemIds.isEmpty()) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "itemIds must be a non-empty array")
        }

        if (toWarehouse.maxCapacity != null) {
            val destinationTotal = itemRepository.findAll().filter { it.warehouseId == toId }.sumOf { it.quantity }
            val candidateItems = body.itemIds.mapNotNull { itemRepository.findById(it) }
            val movingTotal = candidateItems.sumOf { it.quantity }
            if (destinationTotal + movingTotal > toWarehouse.maxCapacity!!) {
                throw ResponseStatusException(HttpStatus.BAD_REQUEST, "transfer would exceed destination warehouse maxCapacity")
            }
        }

        val moved = mutableListOf<Item>()
        for (itemId in body.itemIds) {
            val item = itemRepository.findById(itemId)
            if (item == null || item.warehouseId != fromId) {
                throw ResponseStatusException(HttpStatus.BAD_REQUEST, "item $itemId does not belong to the source warehouse")
            }
            item.warehouseId = toId
            itemRepository.save(item)
            moved.add(item)
        }
        return moved
    }
}
